import { Component } from '@angular/core';
import { SubHeroLogoComponent } from '../shared-ui/sub-hero-logo/sub-hero-logo.component';

@Component({
  standalone: true,
  imports: [
    SubHeroLogoComponent,
  ],
  selector: 'app-not-found',
  templateUrl: './not-found.component.html',
})
export class NotFoundComponent {

}
<section class="main-content">
  <div class="carousel">
    <div class="carousel-image"><img src="../../assets/images/baking-pie.jpg" alt="pie being prepared" /></div>
  </div>

  <app-sub-hero-logo>
    <ng-container title>Oops! That pie isn't ready yet!</ng-container>
    <ng-container sub-title>Check the link and try again</ng-container>
  </app-sub-hero-logo>
</section>
